<script setup>
import { ref, computed, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessageBox, ElMessage } from 'element-plus'
import { useWorkspace } from '../stores/workspace'
import { api, streamApi, addDays, monday, today, shiftName, statusName } from '../services/api'
import ScheduleMatrix from '../components/ScheduleMatrix.vue'
import ValidationResult from '../components/ValidationResult.vue'
import ScheduleCancellation from '../components/ScheduleCancellation.vue'
const s=useWorkspace(), router=useRouter(), tab=ref('view'), dialog=ref(''), report=ref(null), editForm=ref({}), generation=ref({}), rules=ref(null), rulesRevision=ref(0), shiftForm=ref({}), requestForm=ref({}), decision=ref(null)
const generationLoading=ref(false), generationTarget=ref(null), publishContext=ref(null), generationSummary=ref(null)
const generationStage=ref('')
const historicalCorrection=ref(false), correctionReason=ref('')
const cancellationOpen=ref(false)
const requestView=ref('normal'),normalRequests=ref([]),deletedRequests=ref([]),selectedRequests=ref([]),requestPage=ref(1),requestTable=ref(null)
const displayDays=ref(7),requestFilter=ref('all'),editingRequest=ref(null),withdrawRequest=ref(null),requestHistory=ref(null)
const requestRows=computed(()=>{const rows=requestView.value==='deleted'?deletedRequests.value:normalRequests.value;return requestView.value==='normal'&&requestFilter.value!=='all'?rows.filter(row=>row.decision===requestFilter.value):rows})
const visibleRequests=computed(()=>requestRows.value.slice((requestPage.value-1)*10,requestPage.value*10))
const requestSelectable=row=>requestView.value==='deleted'||row.deletable
let generationRequest=0
const formalPeriod=ref(null)
let formalPeriodRequest=0
const draft=computed(()=>s.data.draft), matrix=computed(()=>draft.value||(displayDays.value===14?formalPeriod.value:s.data.published_week))
watch(()=>[displayDays.value,s.week,s.group,draft.value?.id,s.data],async()=>{
  const seq=++formalPeriodRequest;formalPeriod.value=null
  if(displayDays.value!==14||draft.value)return
  try{const result=await api('schedules/period/?'+new URLSearchParams({group:s.group,start_date:s.week}));if(seq===formalPeriodRequest)formalPeriod.value=result}
  catch(error){if(seq===formalPeriodRequest)ElMessage.error('正式排班读取失败：'+error.message)}
},{immediate:true})
const correctionNurse=id=>s.data.nurses.find(n=>n.id===id)?.name||`历史护士 #${id}`
const payload=()=>({...s.groupPayload(),id:draft.value?.id,revision:draft.value?.revision})
async function changeWeek(value){if(s.busy)return;s.week=monday(value||today());await s.run(()=>Promise.resolve(true),'');report.value=null;publishContext.value=null}
function openGenerate(){generationRequest++;generationLoading.value=false;generation.value={...s.groupPayload(),start_date:s.week,duration_days:7,include_requests:true,rotation_only:false};generationTarget.value={week:s.week,draft:draft.value?.start_date===s.week?{id:draft.value.id,revision:draft.value.revision}:null};dialog.value='generate'}
async function selectGenerationWeek(value){
  const seq=++generationRequest;generationTarget.value=null
  if(!value||monday(value)!==value){generationLoading.value=false;return}
  generationLoading.value=true
  try{
    const workspace=await api('workspace/?'+new URLSearchParams({group:generation.value.group,week:value,date:value,shift:s.shift}))
    if(seq===generationRequest)generationTarget.value={week:value,draft:workspace.draft?.start_date===value?{id:workspace.draft.id,revision:workspace.draft.revision}:null}
  }catch(e){if(seq===generationRequest)ElMessage.error(e.message)}finally{if(seq===generationRequest)generationLoading.value=false}
}
async function generate(){
  const target=generationTarget.value,form={...generation.value}
  if(!form.start_date||monday(form.start_date)!==form.start_date)return ElMessage.warning('请选择有效的周一作为排班起始日。')
  if(generationLoading.value||!target||target.week!==form.start_date)return ElMessage.warning('请等待目标周草稿加载完成。')
  if(target.draft){try{await ElMessageBox.confirm(form.start_date+' 起的草稿修订 '+target.draft.revision+' 将重新生成，旧草稿会保留审计记录。继续？','重新生成确认')}catch{return}}
  if(Number(s.group)!==form.group||dialog.value!=='generate')return
  generationStage.value='正在连接排班服务。'
  const r=await s.run(async()=>{const result=await streamApi('schedules/generate-stream/',{...form,revision:target.draft?.revision},text=>generationStage.value=text);if(Number(s.group)===form.group)s.week=form.start_date;return result},'')
  generationStage.value=''
  if(r&&Number(s.group)===form.group){displayDays.value=form.duration_days;generationSummary.value=r.draft.generation_summary;ElMessage.success(`已保存 ${generationSummary.value?.saved_cells??0} 个班次格，请核对校验结果。`);report.value=r.validation;dialog.value='validation';publishContext.value=null}
}
function openEdit(entry){if(!draft.value)return;const n=s.data.nurses[0];editForm.value={...payload(),nurse:entry?.nurse||n?.id,date:entry?.date||s.week,shift:entry?.shift||'A',reason:'工作需要'};dialog.value='edit'}
const currentCell=computed(()=>draft.value?.entries.find(e=>e.nurse===editForm.value.nurse&&e.date===editForm.value.date))
async function edit(){if(!editForm.value.nurse||!editForm.value.date||!editForm.value.shift||!editForm.value.reason?.trim())return ElMessage.warning('请完整选择护士、日期、班次，并填写调整原因。');const r=await s.run(()=>api('schedules/edit/','POST',editForm.value),'已保存修改并重新校验');if(r){report.value=r.validation;dialog.value='validation';publishContext.value=null}}
async function validate(publish=false){
  generationSummary.value=null;historicalCorrection.value=false;correctionReason.value=''
  const context={...payload(),week:s.week};if(!context.id)return
  const r=await s.run(()=>api('schedules/validate/','POST',context),'')
  if(r&&context.group===Number(s.group)&&context.week===s.week){report.value=r;publishContext.value=publish?{...context,revision:r.revision}:null;dialog.value=publish?'publish':'validation'}
}
async function publish(){if(!publishContext.value||!report.value?.valid)return;if(report.value.historical_correction_count&&(!historicalCorrection.value||!correctionReason.value.trim()))return ElMessage.warning('请确认历史更正并填写原因。');const r=await s.run(()=>api('schedules/publish/','POST',{...publishContext.value,historical_correction:historicalCorrection.value,correction_reason:correctionReason.value}),'排班已发布');if(r){dialog.value='success';publishContext.value=null}}
function locate(issue){dialog.value='';if(issue.nurse)openEdit(draft.value.entries.find(e=>e.nurse===issue.nurse&&e.date===issue.date))}
function openRules(){rules.value=JSON.parse(JSON.stringify(s.data.group.rules));rulesRevision.value=s.data.group.revision}
function onTab(value){if(value==='rules')openRules();if(value==='requests')switchRequestView('normal')}
async function saveRules(){if(!rules.value.anchor)return ElMessage.warning('请选择轮转起始日期。');const fields=['anchor','phases','min_staff','min_rest_hours','max_consecutive_days'];const r=await s.run(()=>api('settings/','PATCH',{...s.groupPayload(),revision:rulesRevision.value,rules:Object.fromEntries(fields.map(k=>[k,rules.value[k]]))}),'排班规则已保存');if(r)openRules()}
function openShift(v){shiftForm.value=v?{...v,id:undefined,effective_from:addDays(today(),1)}:{code:'',name:'',start:'08:00:00',end:'12:00:00',next_day:false,hours:4,working:true,color:'#ffe7f1',effective_from:addDays(today(),1),enabled:true};dialog.value='shift'}
async function saveShift(){if(!shiftForm.value.name?.trim()||!shiftForm.value.code?.trim()||!shiftForm.value.start||!shiftForm.value.end||!shiftForm.value.effective_from)return ElMessage.warning('请填写班次名称、代码、起止时间及生效日期。');const r=await s.run(()=>api('shifts/','POST',{...s.groupPayload(),...shiftForm.value}),'班次有效版本已保存');if(r)dialog.value=''}
function openRequest(row=null){editingRequest.value=row;requestForm.value=row?{nurse:row.nurse,kind:row.kind,date:row.date,target_shift:row.target_shift,reason:row.reason,partner_employee_id:s.data.nurses.find(n=>n.id===row.partner)?.employee_id||''}:{nurse:s.data.nurses.find(n=>n.status==='active')?.id,kind:'day',date:today(),target_shift:'DAY',reason:'',partner_employee_id:''};dialog.value='request'}
async function createRequest(){if(!requestForm.value.nurse||!requestForm.value.date||!requestForm.value.target_shift||!requestForm.value.reason?.trim())return ElMessage.warning('请选择申请护士、日期及目标班次，并填写申请理由。');if(requestForm.value.kind==='swap'&&!requestForm.value.partner_employee_id?.trim())return ElMessage.warning('请填写换班对方工号。');const row=editingRequest.value;const r=await s.run(()=>api(row?`requests/${row.id}/edit/`:'requests/create/','POST',{...s.groupPayload(),...requestForm.value,...(row?{revision:row.revision}:{})}),row?.decision==='approved'?'修订已保存，原批准保留；新内容须重新审核':'申请已保存');if(r){dialog.value='';await switchRequestView('normal')}}
async function recordConsent(row){const group=Number(s.group),revision=row.revision;try{await ElMessageBox.confirm('请确认已核实换班对方同意，由当前账号记录。','记录对方同意')}catch{return}if(group!==Number(s.group))return;const r=await s.run(()=>api(`requests/${row.id}/consent/`,'POST',{group,revision,confirmed:true,note:'管理账号已核实对方同意'}),'已记录换班对方同意');if(r)await switchRequestView('normal')}
async function openDecision(row){decision.value={...row,note:'',result:'approved'};requestHistory.value=null;dialog.value='decision';try{requestHistory.value=await api(`requests/${row.id}/versions/?`+new URLSearchParams({group:s.group}))}catch(e){ElMessage.error('申请历史读取失败：'+e.message)}}
function historyDiff(event){const before=event.details?.before,after=event.details?.after;if(!before||!after||event.action!=='编辑调班申请')return '';const display=v=>`${v.date} ${shiftName(v.target_shift)} · ${v.reason||'无理由'}`;return `｜修改前：${display(before)}；修改后：${display(after)}`}
async function decide(){const r=await s.run(()=>api(`requests/${decision.value.id}/decision/`,'POST',{...s.groupPayload(),revision:decision.value.revision,decision:decision.value.result,note:decision.value.note}),'审核结果已保存，批准不等于正式排班已变更');if(r){dialog.value='';await switchRequestView('normal')}}
function openWithdrawal(row){withdrawRequest.value={...row,withdrawReason:'申请需求已取消',note:''};dialog.value='withdraw'}
async function withdraw(){const row=withdrawRequest.value;if(!row?.withdrawReason)return ElMessage.warning('请选择撤销原因。');const reason=row.withdrawReason+(row.note?.trim()?'：'+row.note.trim():'');try{await ElMessageBox.confirm(`确认撤销 ${row.name} 的 ${row.date} 申请？相关草稿需重新校验，已发布排班不会自动修改。`,'二次确认',{type:'warning',confirmButtonText:'确认撤销'})}catch{return}const r=await s.run(()=>api(`requests/${row.id}/withdraw/`,'POST',{...s.groupPayload(),revision:row.revision,reason,confirmed:true}),'申请已撤销，历史和已发布排班已保留');if(r){dialog.value='';await switchRequestView('normal')}}
async function switchRequestView(value){requestView.value=value;requestPage.value=1;selectedRequests.value=[];requestTable.value?.clearSelection()
  const group=s.group
  try{const rows=await api('requests/history/?'+new URLSearchParams({group,state:value}));if(value===requestView.value&&group===s.group){if(value==='deleted')deletedRequests.value=rows;else normalRequests.value=rows}}catch(e){if(group===s.group)ElMessage.error(e.message)}}
async function changeHistory(rows,action){
  if(!rows.length||s.busy)return
  const group=Number(s.group),items=rows.map(row=>({id:row.id,revision:row.revision}))
  try{const preview=await api('requests/history/','POST',{group,action,items,preview:true})
    const blocked=preview.items.filter(item=>!item.eligible),allowed=items.filter(item=>preview.items.some(p=>p.id===item.id&&p.eligible))
    const notice=`选中 ${items.length} 条；可${action==='delete'?'删除':'恢复'} ${allowed.length} 条；不可操作 ${blocked.length} 条。${blocked.map(x=>x.reason).join('；')}\n${preview.schedule_impact}`
    if(!allowed.length){await ElMessageBox.alert(notice,'申请记录预览',{type:'warning'});return}
    await ElMessageBox.confirm(notice,'确认申请记录操作',{type:'warning',confirmButtonText:action==='delete'?'确认删除':'确认恢复'})
    if(group!==Number(s.group))return
    const result=await s.run(()=>api('requests/history/','POST',{group,action,items:allowed,confirmed:true}),action==='delete'?'历史申请已隐藏':'历史申请已恢复')
    if(result){selectedRequests.value=[];requestTable.value?.clearSelection();await switchRequestView(requestView.value)}
  }catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error.message||'申请记录操作失败。')}
}
watch(()=>s.group,()=>{cancellationOpen.value=false;dialog.value='';report.value=null;publishContext.value=null;generationRequest++;generationLoading.value=false;requestView.value='normal';deletedRequests.value=[];selectedRequests.value=[];requestPage.value=1})
watch(()=>s.data.group.id,()=>{if(tab.value==='rules')openRules()})
watch(()=>generation.value.start_date,value=>{if(dialog.value==='generate'&&value!==generationTarget.value?.week)selectGenerationWeek(value)})
watch(()=>requestForm.value.kind,value=>{if(dialog.value==='request'&&value==='day')requestForm.value.target_shift='DAY';if(dialog.value==='request'&&value==='leave')requestForm.value.target_shift='OFF'})
function closeDialog(...names){ if(names.includes(dialog.value)) dialog.value='' }
</script>
<template><div class="page-heading"><div><h1>排班管理</h1><p>{{s.data.group.name}} · 规范轮转、灵活调整、校验后发布</p></div><div v-if="tab==='view'&&s.canEdit" class="actions"><el-button type="primary" @click="openGenerate">智能生成排班</el-button><el-button :disabled="!draft" @click="openEdit()">直接编辑班次</el-button><el-button :disabled="!draft" @click="validate()">排班校验</el-button><el-button :disabled="!draft" :loading="s.busy" @click="s.run(()=>api('schedules/save/','POST',payload()),'草稿已保存至数据库')">保存草稿</el-button><el-button type="primary" :disabled="!draft" @click="validate(true)">审核并发布</el-button></div></div>
<el-alert v-if="tab==='view'&&draft?.request_review_required" title="周期内的调班申请已发生变化，请重新生成草稿并校验；已发布排班不受影响。" type="warning" :closable="false"/>
<el-tabs v-model="tab" class="page-tabs" @tab-change="onTab"><el-tab-pane label="排班视图" name="view"><div class="grid-aside"><section class="card"><div class="card-title"><div><h2>{{s.data.group.name}} · {{s.week}} 至 {{addDays(s.week,displayDays-1)}}</h2><small v-if="draft" class="muted">最近保存：{{new Date(draft.updated_at).toLocaleString('zh-CN')}} · 草稿修订 {{draft.revision}} · {{draft.start_date}} 至 {{draft.end_date}}</small></div></div><div class="filters"><el-radio-group v-model="displayDays" size="small"><el-radio-button :value="7">7天</el-radio-button><el-radio-button :value="14">14天</el-radio-button></el-radio-group><el-button @click="changeWeek(addDays(s.week,-displayDays))">‹ {{displayDays===7?'上一周':'上一周期'}}</el-button><el-date-picker :model-value="s.week" value-format="YYYY-MM-DD" @update:model-value="changeWeek"/><el-button @click="changeWeek(addDays(s.week,displayDays))">{{displayDays===7?'下一周':'下一周期'}} ›</el-button><el-button v-if="s.canEdit" type="danger" plain @click="cancellationOpen=true">撤销时段排班</el-button></div><el-alert v-if="displayDays===14&&draft&&(s.week<draft.start_date||addDays(s.week,13)>draft.end_date)" title="显示周期中的部分日期不属于当前草稿；请切换日期或生成覆盖该周期的草稿。" type="info" :closable="false"/><el-alert v-if="s.data.published_week?.status==='partially_cancelled'" title="本周正式排班部分撤销，须重新校验；当前显示的草稿不代表正式排班。" type="warning" :closable="false"/><el-alert v-else-if="s.data.published_week?.status==='cancelled'" title="本周正式排班已撤销；历史版本仍可在总览查看。" type="warning" :closable="false"/><ScheduleMatrix :entries="matrix?.entries||[]" :nurses="s.data.nurses" :leaders="s.data.group.rules.actual_leaders || {}" :start="s.week" :duration="displayDays" :editable="s.canEdit&&!!draft" :editable-start="draft?.start_date" :editable-end="draft?.end_date" @edit="openEdit"/></section><aside><div class="card"><h3>班次图例</h3><div v-for="sh in s.data.shifts" :key="sh.id" class="legend-row"><span :class="['shift-badge','shift-'+sh.code]">{{sh.name}}</span><small>{{sh.working?sh.start.slice(0,5)+'–'+(sh.next_day?'次日':'')+sh.end.slice(0,5):'休息'}} · {{Number(sh.hours)}}h</small></div></div><div class="card"><h3>排班提示</h3><p class="muted small">班次格可直接编辑。人工修改后人数同步计算，最终发布始终重新执行后端校验。</p><p class="small">待审核申请 <b>{{s.data.pending_request_count}}</b> 项</p><el-button link type="primary" @click="tab='requests'">查看调班申请 →</el-button></div><div class="card"><h3>最近变更</h3><div v-for="log in s.data.logs.filter(l=>/排班|班次/.test(l.action)).slice(0,4)" :key="log.id" class="notice"><b class="small">{{log.action}}</b><p class="small muted">{{new Date(log.created_at).toLocaleString('zh-CN')}}</p></div></div></aside></div></el-tab-pane>
<el-tab-pane label="班次设置" name="shifts"><div class="card"><div class="card-title"><h2>基础班次定义</h2><el-button v-if="s.canEdit" type="primary" @click="openShift()">＋ 新增自定义班次</el-button></div><el-alert title="班次修改创建新的生效版本。已发布记录中的工时快照不会被追溯改变。" type="info" :closable="false"/><el-table :data="s.data.shifts"><el-table-column prop="name" label="班次名称"/><el-table-column prop="code" label="标识"/><el-table-column label="时间段" min-width="160"><template #default="{row}">{{row.working?row.start.slice(0,5)+'–'+(row.next_day?'次日':'')+row.end.slice(0,5):'休息'}}</template></el-table-column><el-table-column label="有效时长"><template #default="{row}">{{Number(row.hours)}} 小时</template></el-table-column><el-table-column label="固定轮转"><template #default="{row}">{{['A','N','POST','OFF'].includes(row.code)?'是':'否'}}</template></el-table-column><el-table-column prop="effective_from" label="生效日期"/><el-table-column label="状态"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column v-if="s.canEdit" label="操作"><template #default="{row}"><el-button link type="primary" @click="openShift(row)">编辑后续版本</el-button></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="排班规则" name="rules"><template v-if="rules"><section class="card"><div class="card-title"><h2>小组轮转规则</h2><div class="actions"><el-button :disabled="!s.canEdit" @click="openRules">取消修改</el-button><el-button type="primary" :disabled="!s.canEdit" :loading="s.busy" @click="saveRules">保存规则</el-button></div></div><div class="steps-flow"><span v-for="code in ['A','N','POST','OFF']" :key="code" :class="'shift-'+code">{{shiftName(code)}}<br/><small>{{code==='N'?'17:00–次日08:00':code==='A'?'08:00–17:00':'休息'}}</small></span></div><el-alert title="轮转顺序固定。个人调班不会改变小组相位；长期白班独立配置。" type="info" :closable="false"/><el-form label-width="140px" :disabled="!s.canEdit"><el-form-item label="轮转起始日期"><el-date-picker v-model="rules.anchor" value-format="YYYY-MM-DD"/></el-form-item><el-form-item v-for="n in 4" :key="n" :label="'第'+n+'小组起始班次'"><el-select v-model="rules.phases[n-1]" style="width:200px"><el-option v-for="(c,i) in ['A','N','POST','OFF']" :key="c" :label="shiftName(c)" :value="i"/></el-select></el-form-item></el-form></section><div class="grid-two section-gap"><section class="card"><h2>人员排班约束</h2><el-form label-width="150px" :disabled="!s.canEdit"><el-form-item label="最短休息间隔（小时）"><el-input-number v-model="rules.min_rest_hours" :min="0" :max="48"/></el-form-item><el-form-item label="最长连续工作天数"><el-input-number v-model="rules.max_consecutive_days" :min="1" :max="31"/></el-form-item><p class="muted small">资格、夜班后休息与时间冲突校验始终启用。数值参数需科室确认。</p></el-form></section><section class="card"><h2>班次人力需求</h2><el-form label-width="120px" :disabled="!s.canEdit"><el-form-item v-for="c in ['A','DAY','N']" :key="c" :label="shiftName(c)+'最低人数'"><el-input-number v-model="rules.min_staff[c]" :min="0" :max="100"/></el-form-item><p class="muted small">夜下休 / 休：—</p></el-form></section></div></template></el-tab-pane>
<el-tab-pane label="调班申请" name="requests"><section class="card">
  <div class="card-title"><h2>调班申请列表</h2><div v-if="s.canEdit" class="actions"><el-button type="danger" plain :disabled="!selectedRequests.length" @click="changeHistory(selectedRequests,requestView==='deleted'?'restore':'delete')">{{requestView==='deleted'?'恢复选中':'删除选中'}}（{{selectedRequests.length}}）</el-button><el-button type="primary" @click="openRequest">代录申请</el-button></div></div>
  <el-radio-group :model-value="requestView" @update:model-value="switchRequestView"><el-radio-button value="normal">正常记录</el-radio-button><el-radio-button value="deleted">已删除记录</el-radio-button></el-radio-group>
  <el-select v-if="requestView==='normal'" v-model="requestFilter" class="request-filter" @change="requestPage=1"><el-option v-for="[v,label] in [['all','全部'],['pending','待审核'],['approved','已批准'],['rejected','已驳回'],['withdrawn','已撤销']]" :key="v" :value="v" :label="label"/></el-select>
  <el-table ref="requestTable" :data="visibleRequests" @selection-change="rows=>selectedRequests=rows"><el-table-column v-if="s.canEdit" type="selection" :selectable="requestSelectable" width="45"/><el-table-column prop="name" label="申请人"/><el-table-column prop="date" label="日期"/><el-table-column label="申请类型"><template #default="{row}">{{({change:'调班',day:'临时白班',leave:'请假',swap:'换班'})[row.kind]}}</template></el-table-column><el-table-column label="目标班次"><template #default="{row}">{{shiftName(row.target_shift)}}</template></el-table-column><el-table-column prop="reason" label="理由" min-width="180"/><el-table-column label="状态" min-width="140"><template #default="{row}"><el-tag :type="['rejected','withdrawn'].includes(row.decision)?'danger':row.decision==='pending'?'warning':row.superseded_by?'info':'success'">{{statusName(row.status)}}</el-tag><small v-if="row.revises" class="muted">修订 v{{row.version_number}}</small></template></el-table-column><el-table-column label="操作" min-width="240"><template #default="{row}"><el-button v-if="requestView==='normal'" link type="primary" @click="openDecision(row)">{{s.canEdit&&row.decision==='pending'?'审核':'查看'}}</el-button><el-button v-if="s.canEdit&&requestView==='normal'&&!row.invalidated_by_deletion&&!row.superseded_by&&['pending','approved'].includes(row.decision)" link type="primary" @click="openRequest(row)">编辑</el-button><el-button v-if="s.canEdit&&requestView==='normal'&&!row.invalidated_by_deletion&&!row.superseded_by&&['pending','approved'].includes(row.decision)" link type="warning" @click="openWithdrawal(row)">撤销</el-button><el-button v-if="s.canEdit&&requestView==='normal'&&row.kind==='swap'&&row.decision==='pending'&&!row.partner_consented&&!row.invalidated_by_deletion" link type="primary" @click="recordConsent(row)">记录对方同意</el-button><el-button v-if="s.canEdit&&requestView==='normal'" link type="danger" :disabled="!row.deletable" :title="row.delete_block_reason" @click="changeHistory([row],'delete')">删除</el-button><el-button v-if="s.canEdit&&requestView==='deleted'" link type="primary" @click="changeHistory([row],'restore')">恢复</el-button></template></el-table-column></el-table>
  <el-pagination v-model:current-page="requestPage" :page-size="10" :total="requestRows.length" layout="total, prev, pager, next" class="section-gap" @current-change="selectedRequests=[];requestTable?.clearSelection()"/>
  <el-alert title="批准申请后需纳入排班生成、校验并重新发布，才会改变正式记录。历史申请隐藏和恢复不改变审批或正式排班。" type="info" :closable="false" class="section-gap"/></section></el-tab-pane></el-tabs>
<ScheduleCancellation v-model="cancellationOpen" :group="s.group" :week="s.week" :nurses="s.data.nurses" :shifts="s.data.shifts" :phases="s.data.group.rules.phases" @changed="s.load(true).catch(e=>ElMessage.error(e.message))"/>
<el-dialog :model-value="dialog==='generate'" title="智能生成排班" width="460px" @close="closeDialog('generate')"><el-form label-position="top"><el-form-item label="排班周期"><el-radio-group v-model="generation.duration_days"><el-radio-button :value="7">单周排班（7天）</el-radio-button><el-radio-button :value="14">双周排班（14天）</el-radio-button></el-radio-group></el-form-item><el-form-item label="排班起始日（周一）"><el-date-picker v-model="generation.start_date" value-format="YYYY-MM-DD" :disabled-date="d=>d.getDay()!==1"/></el-form-item><el-alert v-if="generation.start_date" :title="`本次将生成连续 ${generation.duration_days} 天：${generation.start_date} 至 ${addDays(generation.start_date,generation.duration_days-1)}。`" type="info" :closable="false"/><el-form-item label="人员范围"><el-radio-group v-model="generation.rotation_only"><el-radio :value="false">全部人员（含长期白班）</el-radio><el-radio :value="true">仅轮转人员</el-radio></el-radio-group></el-form-item><el-switch v-model="generation.include_requests" active-text="纳入已批准的申请"/><p class="muted small section-gap">仅轮转人员生成时，人力覆盖校验仍按本组全部在岗人员执行。</p><el-alert v-if="generationStage" :title="generationStage" type="info" :closable="false"/></el-form><template #footer><el-button :disabled="s.busy" @click="dialog=''">取消</el-button><el-button type="primary" :loading="s.busy" @click="generate">生成{{generation.duration_days}}天排班</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='edit'" title="直接编辑班次" width="510px" @close="closeDialog('edit')"><el-form label-position="top"><el-form-item label="护士"><el-select v-model="editForm.nurse" class="full"><el-option v-for="n in s.data.nurses" :key="n.id" :value="n.id" :label="n.name+' · '+n.level"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker v-model="editForm.date" value-format="YYYY-MM-DD" :disabled-date="d=>!draft||d<new Date(draft.start_date+'T00:00:00')||d>new Date(draft.end_date+'T23:59:59')"/></el-form-item><p class="muted small">原定：{{shiftName(currentCell?.original)}} · 当前：{{shiftName(currentCell?.shift)}}<br/>来源：{{currentCell?.source}} {{currentCell?.reason}}</p><el-form-item label="调整后班次"><el-radio-group v-model="editForm.shift"><el-radio-button v-for="sh in s.data.shifts.filter(x=>x.enabled)" :key="sh.id" :value="sh.code">{{sh.name}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="调整原因 *"><el-input v-model="editForm.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="s.busy" @click="edit">保存并校验</el-button></template></el-dialog>
<el-dialog :model-value="['validation','publish'].includes(dialog)" :title="dialog==='publish'?'审核并发布':'排班校验'" width="620px" @close="closeDialog('validation','publish')"><p>{{draft?.start_date}} 至 {{draft?.end_date}} · {{s.data.group.name}}</p><p v-if="generationSummary" class="small muted">生成版本 #{{draft?.generation_version_id}} · {{generationSummary.days}} 天 · {{generationSummary.nurses}} 人 · 已保存 {{generationSummary.saved_cells}} 个班次格，其中工作班次 {{generationSummary.working_shifts}} 条。</p><el-alert v-if="dialog==='publish'&&report?.historical_correction_count" :title="`含 ${report.historical_correction_count} 条已开始或过去的正式排班变更；未接入考勤，须由授权管理人员核实；历史分床保留原版本，进行中的责任须先安全交接。`" type="warning" :closable="false"/><template v-if="dialog==='publish'&&report?.historical_correction_count"><details><summary>查看历史更正前后明细</summary><p v-for="(change,index) in report.historical_corrections" :key="index" class="small muted">{{change.date}} · {{correctionNurse(change.nurse)}} · {{shiftName(change.before)}} → {{shiftName(change.after)}} · 原版本 #{{change.publication}}</p></details><el-checkbox v-model="historicalCorrection">确认按授权历史更正处理</el-checkbox><el-input v-model="correctionReason" type="textarea" maxlength="500" placeholder="请填写历史更正原因"/></template><ValidationResult :report="report" @locate="locate"/><template #footer><el-button @click="dialog=''">返回修改</el-button><el-button v-if="dialog==='validation'" type="primary" :loading="s.busy" @click="validate()">重新校验</el-button><el-button v-else type="primary" :disabled="!report?.valid" :loading="s.busy" @click="publish">确认发布</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='success'" title="排班发布成功" width="430px" @close="closeDialog('success')"><el-result icon="success" title="已生成不可变正式版本" sub-title="正式排班已发布，可在总览中查看。"/><template #footer><el-button type="primary" @click="dialog='';router.push('/overview')">前往总览查看</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='shift'" title="新增 / 编辑班次有效版本" width="590px" @close="closeDialog('shift')"><el-form label-position="top"><div class="form-grid"><el-form-item label="名称"><el-input v-model="shiftForm.name"/></el-form-item><el-form-item label="代码"><el-input v-model="shiftForm.code"/></el-form-item><el-form-item label="开始时间"><el-time-picker v-model="shiftForm.start" value-format="HH:mm:ss"/></el-form-item><el-form-item label="结束时间"><el-time-picker v-model="shiftForm.end" value-format="HH:mm:ss"/></el-form-item><el-form-item label="有效时长（小时）"><el-input-number v-model="shiftForm.hours" :min="0" :max="24"/></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="shiftForm.effective_from" value-format="YYYY-MM-DD"/></el-form-item></div><el-checkbox v-model="shiftForm.next_day">次日结束</el-checkbox><el-checkbox v-model="shiftForm.working">工作班次</el-checkbox><el-checkbox v-model="shiftForm.enabled">启用</el-checkbox></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="s.busy" @click="saveShift">保存后续版本</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='request'" :title="editingRequest?'编辑调班申请':'代录调班申请'" width="480px" @close="closeDialog('request')"><el-alert v-if="editingRequest?.decision==='approved'" title="修改后生成待审核修订。原批准在新修订批准前保留；驳回后原批准仍有效。正式排班不会自动修改。" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="申请护士"><el-select v-model="requestForm.nurse" filterable><el-option v-for="n in s.data.nurses.filter(x=>x.status==='active')" :key="n.id" :value="n.id" :label="n.name+' · '+n.employee_id"/></el-select></el-form-item><el-form-item label="申请类型"><el-select v-model="requestForm.kind"><el-option v-for="[v,l] in [['day','临时白班'],['change','调班'],['leave','请假'],['swap','换班']]" :key="v" :value="v" :label="l"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker v-model="requestForm.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="目标班次"><el-select v-model="requestForm.target_shift"><el-option v-for="sh in s.data.shifts" :key="sh.id" :value="sh.code" :label="sh.name"/></el-select></el-form-item><el-form-item v-if="requestForm.kind==='swap'" label="换班对方工号（须本人同意）"><el-input v-model="requestForm.partner_employee_id"/></el-form-item><el-form-item label="申请理由"><el-input v-model="requestForm.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" @click="createRequest" :loading="s.busy">保存申请</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='withdraw'" title="撤销调班申请" width="520px" @close="closeDialog('withdraw')"><template v-if="withdrawRequest"><p>{{withdrawRequest.name}} · {{withdrawRequest.date}} · {{shiftName(withdrawRequest.target_shift)}}<br/>申请理由：{{withdrawRequest.reason}}<br/>审核状态：{{statusName(withdrawRequest.decision)}} · 审核人：{{withdrawRequest.reviewer||'—'}} · 审核时间：{{withdrawRequest.reviewed_at?new Date(withdrawRequest.reviewed_at).toLocaleString('zh-CN'):'—'}}</p><el-alert :title="`关联草稿 ${withdrawRequest.draft_ids?.length||0} 个，历史正式版本 ${withdrawRequest.publication_ids?.length||0} 个。撤销后请重新校验草稿；正式排班须通过授权更正或重新发布处理。`" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="撤销原因"><el-select v-model="withdrawRequest.withdrawReason"><el-option v-for="reason in ['申请需求已取消','日期或班次填写有误','人员工作安排变化','已通过其他方式调整','重复申请','其他原因']" :key="reason" :label="reason" :value="reason"/></el-select></el-form-item><el-form-item label="补充说明"><el-input v-model="withdrawRequest.note" maxlength="300" type="textarea"/></el-form-item></el-form></template><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="danger" :loading="s.busy" @click="withdraw">撤销申请</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='decision'" title="调班申请详情与审核" width="560px" @close="closeDialog('decision')"><template v-if="decision"><p>{{decision.name}} · {{decision.date}} → {{shiftName(decision.target_shift)}} · 版本 {{decision.version_number}}</p><p>{{decision.reason}}</p><el-alert v-if="decision.revises&&decision.decision==='pending'" title="这是对已批准申请的修订，批准后才替代原申请；驳回时原批准继续有效。" type="warning" :closable="false"/><el-radio-group v-if="s.canEdit&&decision.decision==='pending'" v-model="decision.result"><el-radio value="approved">同意</el-radio><el-radio value="rejected">驳回</el-radio></el-radio-group><el-input v-if="s.canEdit&&decision.decision==='pending'" v-model="decision.note" placeholder="审核意见" type="textarea" class="section-gap"/><p v-else>{{statusName(decision.status)}} · {{decision.review_note}}<br/>{{decision.withdrawal_reason?'撤销原因：'+decision.withdrawal_reason:''}}</p><details v-if="requestHistory"><summary>查看申请版本及操作历史</summary><p v-for="version in requestHistory.versions" :key="version.id" class="small muted">版本 {{version.version_number}} · {{version.date}} · {{shiftName(version.target_shift)}} · {{statusName(version.decision)}} · {{version.reason}}</p><p v-for="event in requestHistory.events" :key="event.id" class="small muted">{{new Date(event.created_at).toLocaleString('zh-CN')}} · {{event.actor}} · {{event.action}}{{historyDiff(event)}}</p></details></template><template #footer><el-button @click="dialog=''">关闭</el-button><el-button v-if="s.canEdit&&decision?.decision==='pending'" type="primary" :loading="s.busy" @click="decide">保存审核结果</el-button></template></el-dialog>
</template>
<style scoped>.request-filter{width:130px;margin-left:12px}</style>
